using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TreatySupplyTests
{
    static readonly EntityId Own=new("org:takeda"),Other=new("org:oda"),Player=new("person:shingen"),Supplier=new("person:nobunaga"),Home=new("site:kofu"),Source=new("site:castle");
    static WorldSession Start()=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],Player.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy,trucePolicy:TruceNegotiations.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void At(WorldSession s,long t){while(s.Seconds<t){var old=s.Seconds;s.SetPaused(false);s.AdvanceTo(t,100000);Assert.True(s.Seconds>old);}}
    static long Arrival(WorldSession s,string id)=>s.DiagnosticSnapshot().Couriers!.Missions.Single(c=>s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==c.Attempt&&a.MessageId==id)).ReadyAt;
    static void Open(WorldSession s,string id)=>Good(s.Open(Player,new(id),s.Revision));
    static readonly Lazy<ContractWorld> Prepared=new(BuildReady);
    static ContractWorld BuildReady(){var s=Start();Good(s.NegotiateTreaty(new(new("request:supply-treaty"),TreatyAction.Propose,Own,Other,Days:30,Clauses:TreatyClause.Supply,NoticeDays:1),Player,s.Revision));var p=s.DiagnosticSnapshot().Treaties!.Papers.Single();At(s,Arrival(s,p.Message)+1);var a=s.DiagnosticSnapshot().Treaties!.Papers.Last();At(s,Arrival(s,a.Message));Open(s,a.Message);Good(s.NegotiateTreaty(new(new("request:supply-confirm"),TreatyAction.Confirm,Own,Other,a.Input.Id),Player,s.Revision));var c=s.DiagnosticSnapshot().Treaties!.Papers.Last();At(s,Arrival(s,c.Message)+1);Good(s.OperateTreaty(new(new("request:actual-supply"),TreatyOperation.RequestSupply,a.Input.Id,Own,Other,ReplyBy:s.Seconds+7*86400,Amount:20,Evidence:"補給米20kgを希望する"),Player,s.Revision));var r=s.DiagnosticSnapshot().Treaties!.Operations.Last();At(s,Arrival(s,r.Message)+1);var receipt=s.DiagnosticSnapshot().Treaties!.Operations.Last();At(s,Arrival(s,receipt.Message));Open(s,receipt.Message);s.SetPaused(true);return s.DiagnosticSnapshot();}
    static WorldSession Ready()=>new(ContractJson.Copy(Prepared.Value));
    static TreatySupplyInput Input(WorldSession s,TreatySupplyAction action,EntityId request,long qty=0)=>new(new("request:physical-supply/"+s.Revision+"/"+action),action,request,qty);
    static TreatySupplyEntry Send(WorldSession s,TreatySupplyInput i){var result=s.ManageTreatySupply(i,Player,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason+System.Text.Json.JsonSerializer.Serialize(new{Now=s.Seconds,Until=s.DiagnosticSnapshot().Treaties?.Supply?.Entries.FirstOrDefault(e=>e.Terms!=null)?.Terms?.Until,PlayerSite=s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Player).Site,SupplierSite=s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Supplier).Site}));return s.DiagnosticSnapshot().Treaties!.Supply!.Entries.Last();}
    static EntityId Arrange(WorldSession s){var request=s.DiagnosticSnapshot().Treaties!.Operations.Single(p=>p.Kind==TreatyOperation.RequestSupply);var e=Send(s,Input(s,TreatySupplyAction.Arrange,request.Input.Id));return e.Root;}
    static TreatySupplyTerms Granted(WorldSession s,EntityId root,bool open=true){var ask=s.DiagnosticSnapshot().Treaties!.Supply!.Papers.Single(p=>p.Root==root&&p.Kind==TreatySupplyPaperKind.Ask);At(s,Arrival(s,ask.Id)+1);var p=s.DiagnosticSnapshot().Treaties!.Supply!.Papers.Single(p=>p.Root==root&&p.Kind==TreatySupplyPaperKind.Offer);At(s,Arrival(s,p.Id));if(open)Open(s,p.Id);return p.Terms!;}
    static void Move(WorldSession s,EntityId site){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:supply-trip/"+s.Revision,NewGameWorld.Node(site.Value)),s.Revision));At(s,s.Seconds+2);At(s,s.GetBranchView(Player).ArrivalAt!.Value+2);Assert.Equal(site,s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Player).Site);}
    static long Reserved(WorldSession s)=>(long)typeof(HouseSalary).GetMethod("Reserved",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic)!.Invoke(null,new object[]{s.DiagnosticSnapshot(),Source,s.Seconds,s.Revision+1})!;
    static long Rice(WorldSession s,EntityId site)=>s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==site).HouseRice;
    [Fact]public void SupplyOfferReservesButDoesNotCreateOrMoveRice(){var s=Ready();long before=Rice(s,Source);var root=Arrange(s);var t=Granted(s,root);Assert.Equal(20,t.Quantity);Assert.Equal(before,Rice(s,Source));Assert.Equal(0,TreatySupply.Cargo(s.DiagnosticSnapshot(),root));Assert.Equal(20,Reserved(s));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void PickupRequiresPersonalOpeningAndActualSourcePresence(){var s=Ready();var root=Arrange(s);Granted(s,root,false);Assert.Equal(ResultCode.NotAvailable,s.ManageTreatySupply(Input(s,TreatySupplyAction.Pickup,root,20),Player,s.Revision).Code);Move(s,Source);Assert.Equal(ResultCode.NotAvailable,s.ManageTreatySupply(Input(s,TreatySupplyAction.Pickup,root,20),Player,s.Revision).Code);Open(s,s.DiagnosticSnapshot().Treaties!.Supply!.Papers.Single(p=>p.Kind==TreatySupplyPaperKind.Offer).Id);Send(s,Input(s,TreatySupplyAction.Pickup,root,20));Assert.Equal(20,TreatySupply.Cargo(s.DiagnosticSnapshot(),root));}
    [Fact]public void SameCarrierActuallyMovesAndPartiallyDeliversToRecipientHouse(){var s=Ready();var root=Arrange(s);Granted(s,root);Move(s,Source);long source=Rice(s,Source),dest=Rice(s,Home);Send(s,Input(s,TreatySupplyAction.Pickup,root,20));Assert.Equal(source-20,Rice(s,Source));Assert.Equal(dest,Rice(s,Home));Assert.Equal(ResultCode.NotAvailable,s.ManageTreatySupply(Input(s,TreatySupplyAction.Deliver,root,10),Player,s.Revision).Code);Move(s,Home);Send(s,Input(s,TreatySupplyAction.Deliver,root,10));Assert.Equal(dest+10,Rice(s,Home));Assert.Equal(10,TreatySupply.Cargo(s.DiagnosticSnapshot(),root));Send(s,Input(s,TreatySupplyAction.Deliver,root,10));Assert.Equal(dest+20,Rice(s,Home));Assert.Equal(0,TreatySupply.Cargo(s.DiagnosticSnapshot(),root));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void ExpiredCargoIsReturnedPhysicallyWithoutRevivingOffer(){var s=Ready();var root=Arrange(s);var t=Granted(s,root);Move(s,Source);long before=Rice(s,Source);Send(s,Input(s,TreatySupplyAction.Pickup,root,20));At(s,t.Until+1);Assert.Equal(ResultCode.NotAvailable,s.ManageTreatySupply(Input(s,TreatySupplyAction.Pickup,root,1),Player,s.Revision).Code);Send(s,Input(s,TreatySupplyAction.Return,root,20));Assert.Equal(before,Rice(s,Source));Assert.Equal(0,TreatySupply.Cargo(s.DiagnosticSnapshot(),root));Assert.Equal(ResultCode.NotAvailable,s.ManageTreatySupply(Input(s,TreatySupplyAction.Pickup,root,1),Player,s.Revision).Code);}
    [Fact]public void CancellationDoesNotTeleportCargoOrReleaseStockBeforeDelivery(){var s=Ready();var root=Arrange(s);Granted(s,root);Move(s,Source);Send(s,Input(s,TreatySupplyAction.Pickup,root,10));long before=Rice(s,Source);var e=Send(s,Input(s,TreatySupplyAction.Cancel,root));Assert.Equal(10,TreatySupply.Cargo(s.DiagnosticSnapshot(),root));Assert.Equal(before,Rice(s,Source));At(s,Arrival(s,e.Paper!)+1);Send(s,Input(s,TreatySupplyAction.Return,root,10));Assert.Equal(before+10,Rice(s,Source));Assert.Equal(ResultCode.NotAvailable,s.ManageTreatySupply(Input(s,TreatySupplyAction.Pickup,root,1),Player,s.Revision).Code);}
    [Fact]public void DuplicateInputDoesNotRepeatPickupAndPrivateSaleCannotUseCargo(){var s=Ready();var root=Arrange(s);Granted(s,root);Move(s,Source);var i=Input(s,TreatySupplyAction.Pickup,root,20);Send(s,i);long before=Rice(s,Source);Assert.Equal(ResultCode.AlreadyAccepted,s.ManageTreatySupply(i,Player,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageTreatySupply(i with{Quantity=21},Player,s.Revision).Code);Assert.Equal(before,Rice(s,Source));Assert.Equal(ResultCode.NotAvailable,s.TradeRice(new(new("request:private-gift-resale"),TradeAction.Quote,Source,Destination:Home,Amount:1),Player,s.Revision).Code);}

    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)][InlineData(8)][InlineData(9)][InlineData(10)][InlineData(11)]public void ActualGenerationRecoveryKeepsRiceOwnerCustodyRouteAndFuture(int phase){var s=Ready();EntityId root=default;TreatySupplyTerms? t=null;if(phase>=1)root=Arrange(s);if(phase>=2)t=Granted(s,root,phase>=3);if(phase==4){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:supply-save-outbound",NewGameWorld.Node(Source.Value)),s.Revision));At(s,s.Seconds+10);}if(phase>=5){Move(s,Source);Send(s,Input(s,TreatySupplyAction.Pickup,root,20));}if(phase==6){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:supply-save-carrying",NewGameWorld.Node(Home.Value)),s.Revision));At(s,s.Seconds+10);}if(phase is 7 or 8 or 11){Move(s,Home);if(phase==11){var heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;var id=new EntityId("request:supply-custodian-retire");Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Own,heir),Player,s.Revision));Good(s.ManageHouseSuccession(new(new("request:supply-custodian-confirm"),HouseSuccessionAction.Confirm,Own,Original:id),Player,s.Revision));At(s,s.Seconds+1);}Send(s,Input(s,TreatySupplyAction.Deliver,root,10));if(phase==8)Send(s,Input(s,TreatySupplyAction.Deliver,root,10));}if(phase==9){var cancel=Send(s,Input(s,TreatySupplyAction.Cancel,root));At(s,Arrival(s,cancel.Paper!)+1);}if(phase==10){At(s,t!.Until+1);Send(s,Input(s,TreatySupplyAction.Return,root,20));}Save(s,phase);}
    static void Save(WorldSession s,int phase){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"treaty-supply-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"supply",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("supply"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(TreatySupply.View(w)),ContractJson.Write(TreatySupply.View(host.Current.DiagnosticSnapshot())));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,"treaty-supply-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"treaty-supply-"+phase+".restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ForgedOfferStockAuthorityOrDestinationCannotLoad(int n){var s=Ready();var root=Arrange(s);Granted(s,root);var w=s.DiagnosticSnapshot();var index=Array.FindIndex(w.Treaties!.Supply!.Entries,e=>e.Terms!=null);var e=w.Treaties.Supply.Entries[index];var t=e.Terms!;w.Treaties.Supply.Entries[index]=e with{Terms=n switch{0=>t with{Quantity=3000},1=>t with{Destination=Source},2=>t with{Supplier=Player},3=>t with{Authority=t.Authority with{Owner=Own}},_=>t with{Until=t.Until+86400}}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData("Policy")][InlineData("Entries")][InlineData("Papers")][InlineData("Openings")][InlineData("Failures")]public void NewExtensionRequiredFieldsStayRequired(string field){var s=Ready();Arrange(s);var node=System.Text.Json.Nodes.JsonNode.Parse(ContractJson.Write(s.DiagnosticSnapshot()))!;node["Treaties"]!["Supply"]!.AsObject().Remove(field);Assert.Throws<InvalidDataException>(()=>ContractJson.Read<ContractWorld>(System.Text.Encoding.UTF8.GetBytes(node.ToJsonString())));}
    [Fact]public void ACurrentHeadAtTheRecipientHouseReceivesTheRiceWithoutChangingCargoOwnershipEarly(){var s=Ready();var root=Arrange(s);Granted(s,root);Move(s,Source);Send(s,Input(s,TreatySupplyAction.Pickup,root,20));Move(s,Home);var heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;var id=new EntityId("request:supply-new-receiver");Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Own,heir),Player,s.Revision));Good(s.ManageHouseSuccession(new(new("request:supply-new-receiver-confirm"),HouseSuccessionAction.Confirm,Own,Original:id),Player,s.Revision));At(s,s.Seconds+1);var e=Send(s,Input(s,TreatySupplyAction.Deliver,root,20));Assert.Equal(heir,e.Receiver);Assert.Equal(Own,e.Authority!.Owner);Assert.Equal(0,TreatySupply.Cargo(s.DiagnosticSnapshot(),root));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void APartiallyDeliveredGiftDoesNotBecomePrivateSalaryRice(){var s=Ready();var root=Arrange(s);Granted(s,root);Move(s,Source);Send(s,Input(s,TreatySupplyAction.Pickup,root,20));Move(s,Home);long before=HouseSalary.PrivateRice(s.DiagnosticSnapshot(),Player);Send(s,Input(s,TreatySupplyAction.Deliver,root,10));Assert.Equal(before,HouseSalary.PrivateRice(s.DiagnosticSnapshot(),Player));Assert.Equal(10,TreatySupply.Delivered(s.DiagnosticSnapshot(),s.DiagnosticSnapshot().Treaties!.Operations.Single(p=>p.Kind==TreatyOperation.RequestSupply).Input.Id));Assert.Contains(TreatyNegotiations.OperationView(s.DiagnosticSnapshot()),v=>v.Status.Contains("実納入 10/20kg"));}
    [Fact]public void OverCollectionAndOverDeliveryAreRejectedWithoutChangingStock(){var s=Ready();var root=Arrange(s);Granted(s,root);Move(s,Source);long before=Rice(s,Source);Assert.Equal(ResultCode.NotAvailable,s.ManageTreatySupply(Input(s,TreatySupplyAction.Pickup,root,21),Player,s.Revision).Code);Assert.Equal(before,Rice(s,Source));Send(s,Input(s,TreatySupplyAction.Pickup,root,20));Move(s,Home);before=Rice(s,Home);Assert.Equal(ResultCode.NotAvailable,s.ManageTreatySupply(Input(s,TreatySupplyAction.Deliver,root,21),Player,s.Revision).Code);Assert.Equal(before,Rice(s,Home));}

    [Fact]public void CancellationReleasesReservationOnlyAfterSupplierPersonallyReceivesIt(){var s=Ready();var root=Arrange(s);Granted(s,root);long stock=Rice(s,Source);var cancel=Send(s,Input(s,TreatySupplyAction.Cancel,root));Assert.Equal(20,Reserved(s));At(s,Arrival(s,cancel.Paper!)+1);Assert.Equal(0,Reserved(s));Assert.Equal(stock,Rice(s,Source));Assert.Equal(0,TreatySupply.Cargo(s.DiagnosticSnapshot(),root));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void AnUnwillingSupplierFixtureReturnsAPhysicalRefusal(){var world=ContractJson.Copy(Prepared.Value);world.Characters=world.Characters.Select(c=>c.Id==Supplier?c with{WillObey=false}:c).ToArray();var s=new WorldSession(world);var root=Arrange(s);var ask=s.DiagnosticSnapshot().Treaties!.Supply!.Papers.Single(p=>p.Root==root);At(s,Arrival(s,ask.Id)+1);var refusal=s.DiagnosticSnapshot().Treaties!.Supply!.Papers.Single(p=>p.Kind==TreatySupplyPaperKind.Refusal);Assert.Null(refusal.Terms);Assert.DoesNotContain(TreatySupply.View(s.DiagnosticSnapshot()),c=>c.Stage.Contains("確保できない"));At(s,Arrival(s,refusal.Id));Open(s,refusal.Id);Assert.Contains(TreatySupply.View(s.DiagnosticSnapshot()),c=>c.Stage.Contains("確保できない"));Assert.Equal(0,TreatySupply.Cargo(s.DiagnosticSnapshot(),root));}

    static string Failure(WorldSession s,string paper)=>s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==paper)).Id;
    [Fact]public void LostAskRequiresPersonallyOpenedFailureAndKeepsOriginalDeadline(){var s=Ready();var root=Arrange(s);var ask=s.DiagnosticSnapshot().Treaties!.Supply!.Papers.Single();s.DiagnosticTransport((m,t)=>HakutaiKagami.Core.Messaging.MessageFlow.Fail(m,ask.Id));At(s,Arrival(s,ask.Id)+1);var failure=Failure(s,ask.Id);At(s,Arrival(s,failure));var retry=Input(s,TreatySupplyAction.Resend,root) with{Original=ask.Id};Assert.Equal(ResultCode.NotAvailable,s.ManageTreatySupply(retry,Player,s.Revision).Code);Open(s,failure);Send(s,retry);var copy=s.DiagnosticSnapshot().Treaties!.Supply!.Papers.Last();Assert.Equal(ask.Deadline,copy.Deadline);Assert.Equal(ask.ObservedAt,copy.ObservedAt);Assert.Equal(ask.Address,copy.Address);Assert.Equal(ask.Id,copy.CopyOf);At(s,Arrival(s,copy.Id)+1);Assert.Single(s.DiagnosticSnapshot().Treaties!.Supply!.Entries,e=>e.Input.Action==TreatySupplyAction.Grant);Assert.Equal(20,Reserved(s));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void NpcResendsLostOfferOnlyAfterPhysicalFailureAndReservesOnce(){var s=Ready();var root=Arrange(s);var ask=s.DiagnosticSnapshot().Treaties!.Supply!.Papers.Single();At(s,Arrival(s,ask.Id)+1);var offer=s.DiagnosticSnapshot().Treaties!.Supply!.Papers.Single(p=>p.Kind==TreatySupplyPaperKind.Offer);s.DiagnosticTransport((m,t)=>HakutaiKagami.Core.Messaging.MessageFlow.Fail(m,offer.Id));At(s,Arrival(s,offer.Id)+1);Assert.Single(s.DiagnosticSnapshot().Treaties!.Supply!.Papers,p=>p.Kind==TreatySupplyPaperKind.Offer);var f=Failure(s,offer.Id);At(s,Arrival(s,f)+1);var copies=s.DiagnosticSnapshot().Treaties!.Supply!.Papers.Where(p=>p.Kind==TreatySupplyPaperKind.Offer).ToArray();Assert.Equal(2,copies.Length);Assert.Equal(offer.Terms,copies[1].Terms);Assert.Equal(offer.ObservedAt,copies[1].ObservedAt);Assert.Equal(20,Reserved(s));At(s,Arrival(s,copies[1].Id));Open(s,copies[1].Id);Move(s,Source);Send(s,Input(s,TreatySupplyAction.Pickup,root,20));Assert.Equal(20,TreatySupply.Cargo(s.DiagnosticSnapshot(),root));Assert.Equal(ResultCode.NotAvailable,s.ManageTreatySupply(Input(s,TreatySupplyAction.Pickup,root,1),Player,s.Revision).Code);new WorldSession(s.DiagnosticSnapshot());}
}
